def check_solution(a, b, c):
    """Checks if the triple (a, b, c) satisfies the equation."""
    # Equation: a^3 * (b^3 + c^3) = 2012 * (abc + 2)
    lhs = a**3 * (b**3 + c**3)
    rhs = 2012 * (a * b * c + 2)
    return lhs == rhs

solutions = []
max_c = 10
start_a = 1

# Iterate over a = 1, 2, 3 as requested, but extend search if needed within constraints
for a in range(start_a, 4):
    if a > max_c:
        break
    for b in range(a, max_c + 1):
        for c in range(b, max_c + 1):
            if check_solution(a, b, c):
                solutions.append((a, b, c))

print(f"Solutions found for a in [1, 2, 3] and a <= b <= c <= 10: {solutions}")

